import{_ as r,o as t,c as a,a2 as o}from"./chunks/framework.DqYch1Cg.js";const m=JSON.parse('{"title":"MVVM、响应式与数据流自测","description":"","frontmatter":{},"headers":[],"relativePath":"学习自测/16patterns/q_pn_11-mvvm.md","filePath":"学习自测/16patterns/q_pn_11-mvvm.md","lastUpdated":1794211306000}'),n={name:"学习自测/16patterns/q_pn_11-mvvm.md"};function s(i,e,p,l,d,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="mvvm、响应式与数据流自测" tabindex="-1">MVVM、响应式与数据流自测 <a class="header-anchor" href="#mvvm、响应式与数据流自测" aria-label="Permalink to &quot;MVVM、响应式与数据流自测&quot;">​</a></h1><h2 id="_1-mvvm-是什么-和双向绑定等价吗" tabindex="-1">1. MVVM 是什么？和双向绑定等价吗？ <a class="header-anchor" href="#_1-mvvm-是什么-和双向绑定等价吗" aria-label="Permalink to &quot;1. MVVM 是什么？和双向绑定等价吗？&quot;">​</a></h2><p><strong>参考回答：</strong> MVVM 按 Model、View、ViewModel 划分职责。Model 承载数据与业务，View 负责展示，ViewModel 提供视图所需状态与操作，让视图和业务之间更容易分离。自动绑定是常见手段，但双向绑定不是 MVVM 的唯一定义，也不是所有状态都应该双向共享。</p><p><strong>追问：</strong> Vue 应用中服务、组件状态和模板怎样对应这些职责？映射是理解架构的工具，不必把每个框架文件硬塞进某一层。</p><h2 id="_2-vue-2-和-vue-3-响应式有什么差异" tabindex="-1">2. Vue 2 和 Vue 3 响应式有什么差异？ <a class="header-anchor" href="#_2-vue-2-和-vue-3-响应式有什么差异" aria-label="Permalink to &quot;2. Vue 2 和 Vue 3 响应式有什么差异？&quot;">​</a></h2><p><strong>参考回答：</strong> Vue 2 主要基于 Object.defineProperty，对新增 / 删除属性和部分数组操作有使用限制；Vue 3 的 reactive 以 Proxy 为核心，ref 等还有不同实现形式。Proxy 只是拦截机制，框架仍要做依赖追踪、触发、调度和嵌套对象处理。</p><p><strong>追问：</strong> 为什么解构 reactive 对象的普通标量属性后会失去响应式连接？为什么 watch 要传 getter / ref 等合法来源？参见<a href="/FE-prepare-interview/概念与原理/07vue/s_vue_1-reactive">Vue 响应式原理</a>。</p><h2 id="_3-双向绑定和单向数据流冲突吗" tabindex="-1">3. 双向绑定和单向数据流冲突吗？ <a class="header-anchor" href="#_3-双向绑定和单向数据流冲突吗" aria-label="Permalink to &quot;3. 双向绑定和单向数据流冲突吗？&quot;">​</a></h2><p><strong>参考回答：</strong> Vue 组件默认依然是 props 向下、事件向上；v-model 可以看成特定属性与更新事件的约定。父组件拥有状态，子组件报告修改意图，比子组件直接改父组件数据更容易追踪。React 的单向数据流也能实现表单交互，不能由是否双向绑定判断框架优劣。</p><p><strong>追问：</strong> 同一状态被多处展示时谁拥有它？用 computed 派生与 watcher 维护副本，哪一种更容易保持一致？</p><h2 id="_4-响应式更新为什么不等于同步修改-dom" tabindex="-1">4. 响应式更新为什么不等于同步修改 DOM？ <a class="header-anchor" href="#_4-响应式更新为什么不等于同步修改-dom" aria-label="Permalink to &quot;4. 响应式更新为什么不等于同步修改 DOM？&quot;">​</a></h2><p><strong>参考回答：</strong> 状态变化可以立即发生，但 DOM 更新通常由框架调度批处理。需要等待对应 DOM 刷新时使用 nextTick 等机制；副作用还要有清理与取消，防止旧请求覆盖新状态。nextTick 不代表图片加载、网络完成或浏览器已经绘制所有内容。</p><p><strong>追问验证：</strong> 输入框触发搜索，用 watcher 取消旧请求并校验结果有效性；组件卸载时清理监听和计时器。历史 AngularJS 脏检查可作为对比，不代表当代所有 Angular 版本的实现。</p><blockquote><p>来源：<a href="https://github.com/Fridolph/Fridolph/tree/c3a1eda8e0f7fe08d8ec54e07d07db514cbfc5d7/interviewMap/%E6%A1%86%E6%9E%B6%E9%80%9A%E8%AF%86/mvvm.md" target="_blank" rel="noreferrer">个人 interviewMap / MVVM</a>；<a href="https://cn.vuejs.org/guide/extras/reactivity-in-depth.html" target="_blank" rel="noreferrer">Vue 响应式深入</a>；<a href="https://cn.vuejs.org/guide/components/v-model.html" target="_blank" rel="noreferrer">组件 v-model</a>。</p></blockquote>',14)])])}const _=r(n,[["render",s]]);export{m as __pageData,_ as default};
